export async function discoverScopedRuntime(
  configDir: string,
  readinessProbe: ReadinessProbe = probeReadiness,
  options: { cleanupStale?: boolean } = {},
): Promise<ScopedRuntime> {
  let info: ServerPidInfo | null;
  try {
    info = readPidFile(configDir);
  } catch (error) {
    if (error instanceof PidFileReadError) {
      logger.error(error.message);
      return { status: 'error', info: null, error: error.message };
    }
    throw error;
  }

  if (!info) {
    if (fs.existsSync(getPidFilePath(configDir))) {
      return { status: 'error', info: null, error: 'Runtime PID metadata is malformed; retained for manual recovery.' };
    }
    return { status: 'not-running', info: null };
  }

  // Tier 1: dead process → delete the stale PID file, report not-running.
  // Delete only if the file still records this dead PID: a newer runtime may
  // have replaced it between the read above and here, and we must not strand it.
  const identityStatus = inspectProcessIdentity(info.pid, info.processIdentity);
  if (identityStatus === 'unknown') {
    return {
      status: 'error',
      info: null,
      error: processIdentityRecoveryMessage(info.pid, info.processIdentity),
    };
  }
  if (identityStatus === 'dead') {
    if (options.cleanupStale !== false) {
      logger.warn(`PID file points to dead process (PID: ${info.pid}); removing stale PID file`);
      cleanupPidFileIfMatches(configDir, info);
    }
    return { status: 'not-running', info: null };
  }

  // Tier 2: alive but unreachable → retain the PID file, report not-usable.
  const reachable = await readinessProbe(info);
  if (!reachable) {
    return { status: 'unreachable', info };
  }

  return { status: 'running', info };
}

public handleUnexpectedExit(exit: BackendExitFacts): void {
  if (this.state === 'stopped' || !this.policy.restartOnExit) {
    return;
  }

  const generation = this.beginNewOperation();
  this.currentPid = null;
  this.lastExit = {
    code: exit.code,
    signal: exit.signal,
    pid: exit.pid ?? null,
    at: exit.at ? new Date(exit.at) : this.now(),
  };
  this.lastError = null;
  this.scheduleNextAttempt(generation);

